def build_itp_part_a_items(pack_num: int) -> list[dict]:
    """Builds 30 Listening Part A items (Q001..Q030) for pack 1..5."""
    items = []
    entries = _PART_A[pack_num]
    assert len(entries) == 30, f"Pack {pack_num} Part A count {len(entries)} != 30"
    for idx, (tag, qtext, turns, opts, cidx, mod, diff, exp) in enumerate(entries, start=1):
        qid = f"ITP-L1-0{pack_num}-Q{idx:03d}"
        aid = f"ITP0{pack_num}-L{idx:02d}"
        prompt = f"Listen to Part A dialogue {idx} ({tag}). {qtext}"
        items.append(
            rotated_mcq(
                qid=qid,
                section="LISTENING",
                prompt=prompt,
                options=opts,
                correct_idx=cidx,
                explanation=exp,
                rationale_source=mod,
                difficulty=diff,
                seed=pack_num * 7 + idx,
                audio_id=aid,
                audio_turns=turns,
            ),
        )
    return items
